CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(50) UNIQUE NOT NULL,
  "email" varchar(100) UNIQUE NOT NULL,
  "password_hash" varchar(255),
  "phone" varchar(20) UNIQUE,
  "referral_code" varchar(50) UNIQUE NOT NULL,
  "is_email_verified" boolean DEFAULT false,
  "is_phone_verified" boolean DEFAULT false,
  "two_factor_secret" text,
  "two_factor_enabled" boolean DEFAULT false,
  "failed_login_attempts" int DEFAULT 0,
  "lockout_until" timestamp,
  "password_changed_at" timestamp,
  "last_login_at" timestamp,
  "last_login_ip" varchar(45),
  "role" varchar(20) NOT NULL DEFAULT 'buyer',
  "status" varchar(20) NOT NULL DEFAULT 'active',
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp DEFAULT (now())
);

CREATE TABLE "user_social_accounts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "provider" varchar(20) NOT NULL,
  "provider_user_id" varchar(100) NOT NULL,
  "phone_number" varchar(20),
  "provider_email" varchar(100),
  "raw_data" text,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "user_refresh_tokens" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "token_hash" varchar(255) NOT NULL,
  "device_info" varchar(255),
  "ip_address" varchar(45),
  "is_revoked" boolean DEFAULT false,
  "expires_at" timestamp NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "password_reset_tokens" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "token_hash" varchar(255) NOT NULL,
  "expires_at" timestamp NOT NULL,
  "is_used" boolean DEFAULT false,
  "ip_address" varchar(45),
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "security_audit_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint,
  "action" varchar(100) NOT NULL,
  "ip_address" varchar(45),
  "user_agent" text,
  "metadata" text,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "telegram_notification_settings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint UNIQUE NOT NULL,
  "telegram_chat_id" varchar(50) UNIQUE,
  "notify_on_order" boolean DEFAULT true,
  "notify_on_payment" boolean DEFAULT true,
  "notify_on_chat" boolean DEFAULT true,
  "notify_on_dispute" boolean DEFAULT true,
  "notify_on_payout" boolean DEFAULT true,
  "is_active" boolean DEFAULT true
);

CREATE TABLE "games" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(100) NOT NULL,
  "platform" varchar(50) NOT NULL,
  "icon_url" varchar(255),
  "is_active" boolean DEFAULT true
);

CREATE TABLE "game_accounts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "seller_id" bigint NOT NULL,
  "game_id" bigint NOT NULL,
  "title" varchar(150) NOT NULL,
  "description" text,
  "price" decimal(10,2) NOT NULL,
  "server_region" varchar(50) NOT NULL,
  "rank_level" varchar(50),
  "delivery_type" varchar(20) NOT NULL DEFAULT 'instant',
  "is_platform_owned" boolean DEFAULT false,
  "status" varchar(20) NOT NULL DEFAULT 'available',
  "reserved_until" timestamp,
  "view_count" int DEFAULT 0,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "game_account_binds" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "game_account_id" bigint NOT NULL,
  "bind_provider" varchar(50) NOT NULL,
  "bind_status" varchar(30) NOT NULL,
  "note" varchar(255)
);

CREATE TABLE "account_credentials" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "game_account_id" bigint UNIQUE NOT NULL,
  "key_version" int DEFAULT 1,
  "initialization_vector" varchar(64) NOT NULL,
  "auth_tag" varchar(64) NOT NULL,
  "encrypted_login_identifier" text NOT NULL,
  "encrypted_login_password" text NOT NULL,
  "encrypted_backup_codes" text,
  "extra_instructions" text,
  "revealed_at" timestamp
);

CREATE TABLE "account_images" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "game_account_id" bigint NOT NULL,
  "image_url" varchar(255) NOT NULL,
  "is_primary" boolean DEFAULT false,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "orders" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_number" varchar(50) UNIQUE NOT NULL,
  "buyer_id" bigint NOT NULL,
  "seller_id" bigint NOT NULL,
  "game_account_id" bigint UNIQUE NOT NULL,
  "subtotal_amount" decimal(10,2) NOT NULL,
  "discount_amount" decimal(10,2) NOT NULL DEFAULT 0,
  "total_amount" decimal(10,2) NOT NULL,
  "platform_fee" decimal(10,2) NOT NULL DEFAULT 0,
  "seller_net_amount" decimal(10,2) NOT NULL,
  "listing_snapshot" text,
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "account_warranties" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" bigint UNIQUE NOT NULL,
  "warranty_type" varchar(50) NOT NULL,
  "warranty_fee" decimal(10,2) NOT NULL DEFAULT 0,
  "status" varchar(20) NOT NULL DEFAULT 'active',
  "start_date" timestamp DEFAULT (now()),
  "end_date" timestamp,
  "claim_reason" text,
  "claim_resolved_at" timestamp
);

CREATE TABLE "payments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" bigint UNIQUE NOT NULL,
  "transaction_id" varchar(100) UNIQUE NOT NULL,
  "payment_method" varchar(50) NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "paid_at" timestamp
);

CREATE TABLE "wallets" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint UNIQUE NOT NULL,
  "balance" decimal(10,2) NOT NULL DEFAULT 0,
  "updated_at" timestamp DEFAULT (now())
);

CREATE TABLE "wallet_transactions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "wallet_id" bigint NOT NULL,
  "order_id" bigint,
  "withdrawal_request_id" bigint,
  "transaction_type" varchar(20) NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "balance_after" decimal(10,2) NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "withdrawal_requests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "bank_name" varchar(50) NOT NULL,
  "account_number" varchar(50) NOT NULL,
  "account_name" varchar(100) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "admin_notes" text,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "disputes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" bigint UNIQUE NOT NULL,
  "raised_by" bigint NOT NULL,
  "reason" varchar(150) NOT NULL,
  "description" text NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'open',
  "admin_notes" text,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "coupons" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(50) UNIQUE NOT NULL,
  "discount_type" varchar(20) NOT NULL,
  "discount_value" decimal(10,2) NOT NULL,
  "min_order_amount" decimal(10,2) DEFAULT 0,
  "max_discount_amount" decimal(10,2),
  "usage_limit" int,
  "used_count" int DEFAULT 0,
  "per_user_limit" int DEFAULT 1,
  "valid_from" timestamp DEFAULT (now()),
  "valid_until" timestamp NOT NULL,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "coupon_redemptions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "coupon_id" bigint NOT NULL,
  "order_id" bigint UNIQUE NOT NULL,
  "user_id" bigint NOT NULL,
  "discount_amount" decimal(10,2) NOT NULL,
  "redeemed_at" timestamp DEFAULT (now())
);

CREATE TABLE "user_referrals" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "referrer_id" bigint NOT NULL,
  "referee_id" bigint UNIQUE NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "referral_rewards" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "referral_id" bigint NOT NULL,
  "referrer_id" bigint NOT NULL,
  "order_id" bigint NOT NULL,
  "reward_amount" decimal(10,2) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'credited',
  "created_at" timestamp DEFAULT (now())
);

CREATE UNIQUE INDEX ON "user_social_accounts" ("provider", "provider_user_id");

CREATE UNIQUE INDEX ON "user_social_accounts" ("provider", "phone_number");

CREATE UNIQUE INDEX ON "game_account_binds" ("game_account_id", "bind_provider");

COMMENT ON COLUMN "game_accounts"."reserved_until" IS 'Auto reset to available if payment expires';

COMMENT ON COLUMN "orders"."subtotal_amount" IS 'Original listing price';

COMMENT ON COLUMN "orders"."discount_amount" IS 'Coupon discount covered by platform';

COMMENT ON COLUMN "orders"."total_amount" IS 'Actual cash paid by buyer: subtotal - discount';

COMMENT ON COLUMN "orders"."platform_fee" IS 'Commission deducted from subtotal';

COMMENT ON COLUMN "orders"."seller_net_amount" IS 'Net credit for seller: subtotal - platform_fee';

COMMENT ON COLUMN "orders"."listing_snapshot" IS 'Immutable JSON snapshot of account data at checkout time';

COMMENT ON COLUMN "wallet_transactions"."withdrawal_request_id" IS 'Linked if transaction is withdrawal or withdrawal_refund';

COMMENT ON COLUMN "wallet_transactions"."transaction_type" IS 'earning, referral_reward, withdrawal, withdrawal_refund, refund';

COMMENT ON COLUMN "wallet_transactions"."balance_after" IS 'Immutable balance checkpoint for financial audit';

COMMENT ON COLUMN "withdrawal_requests"."status" IS 'pending, approved, rejected';

ALTER TABLE "user_social_accounts" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

