ALTER TABLE "game_accounts" ADD FOREIGN KEY ("id") REFERENCES "account_credentials" ("game_account_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "account_images" ADD FOREIGN KEY ("game_account_id") REFERENCES "game_accounts" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "orders" ADD FOREIGN KEY ("buyer_id") REFERENCES "users" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "orders" ADD FOREIGN KEY ("seller_id") REFERENCES "users" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "game_accounts" ADD FOREIGN KEY ("id") REFERENCES "orders" ("game_account_id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "orders" ADD FOREIGN KEY ("id") REFERENCES "account_warranties" ("order_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "orders" ADD FOREIGN KEY ("id") REFERENCES "payments" ("order_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users" ADD FOREIGN KEY ("id") REFERENCES "wallets" ("user_id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "wallet_transactions" ADD FOREIGN KEY ("wallet_id") REFERENCES "wallets" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "wallet_transactions" ADD FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "wallet_transactions" ADD FOREIGN KEY ("withdrawal_request_id") REFERENCES "withdrawal_requests" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

